// git-course.js — parcours Git rapide et pratique.
// Réutilise le terminal + VFS de node-studio.js et ajoute un état Git pédagogique cohérent.

LEARNING_PATHS.push({ id:"git", title:"Git", subtitle:"3 niveaux · parcours rapide", description:"Maîtrise le workflow Git essentiel en pratiquant dans un dépôt virtuel.", href:"/git-parcours", mark:"Git" });

const GIT_COURSE_LEVELS=[
  {id:"g1",number:1,title:"Les bases essentielles",description:"Dépôt, working tree, staging, commits, status, log et diff.",available:true},
  {id:"g2",number:2,title:"Branches et historique",description:"Branches, switch, merge, conflits, restore et .gitignore.",available:true},
  {id:"g3",number:3,title:"Dépôt distant et workflow réel",description:"Remote, clone, fetch, pull, push et routine quotidienne.",available:true}
];

const GIT_COURSE_LESSONS=[
  {id:"git-intro",level:1,title:"Git, dépôt et historique",objective:"Comprendre Git, GitHub et les trois zones essentielles.",explanations:["Git est un système de gestion de versions local : il garde des points d'historique de ton projet.","GitHub, GitLab ou Bitbucket hébergent des dépôts distants ; Git reste l'outil qui crée les commits et branches."],code:"Working tree → git add → Staging area → git commit → Historique",details:["Working tree : fichiers actuels.","Staging area : prochaine version préparée.","Commit : instantané enregistré dans l'historique."],mistakes:["Confondre Git et GitHub.","Créer fichier_final_v2_final.js au lieu d'utiliser l'historique."],studio:"intro"},
  {id:"git-init-status",level:1,title:"git init et git status",objective:"Initialiser un dépôt et lire son état.",explanations:["git init transforme le dossier courant en dépôt Git.","git status est le réflexe numéro 1 : il te dit ce qui est non suivi, modifié ou prêt à être commité."],code:"mkdir mon-projet\ncd mon-projet\ngit init\ntouch index.html\ngit status",details:["Untracked = Git voit le fichier mais ne le suit pas encore.","Un dépôt est local tant qu'aucun remote n'est configuré."],mistakes:["Lancer une commande Git hors dépôt.","Faire git add . sans lire status."],studio:"init"},
  {id:"git-add-commit",level:1,title:"git add et premier commit",objective:"Préparer puis enregistrer une version propre.",explanations:["git add place la version actuelle d'un fichier dans la staging area.","git commit transforme le contenu staged en point d'historique."],code:'git add index.html\ngit status\ngit commit -m "Ajoute la page d’accueil"',details:["Staged ne veut pas dire commité.","Un bon message décrit clairement le changement."],mistakes:["Messages vagues : update, test, changes.","Committer des secrets."],studio:"commit"},
  {id:"git-log-diff",level:1,title:"git log et git diff",objective:"Lire l'historique et comprendre ce qui a changé.",explanations:["git log --oneline affiche un historique compact.","git diff compare le working tree avec la version staged ; git diff --staged compare la staging area au dernier commit."],code:"git log --oneline\ngit diff\ngit diff --staged",details:["Les lignes + sont ajoutées, les lignes - supprimées.","Après git add, git diff peut devenir vide car la modification est staged."],mistakes:["Committer sans vérifier le diff.","Confondre diff et log."],studio:"diff"},
  {id:"git-branch-switch",level:2,title:"Branches et git switch",objective:"Travailler sans toucher directement à main.",explanations:["Une branche est un pointeur vers un commit.","git switch -c feature/navbar crée puis active une branche."],code:"git branch\ngit switch -c feature/navbar",details:["* indique la branche courante.","Les fichiers reflètent la version de la branche active."],mistakes:["Tout développer directement sur main.","Changer de branche avec des modifications non protégées."],studio:"branch"},
  {id:"git-merge",level:2,title:"Fusionner avec git merge",objective:"Ramener une fonctionnalité dans main.",explanations:["Après ton travail sur une branche, reviens sur main puis fusionne la branche.","Git peut faire un fast-forward ou créer un commit de merge selon l'historique."],code:"git switch main\ngit merge feature/navbar",details:["Le merge intègre l'historique de la branche cible.","Vérifie status et log après la fusion."],mistakes:["Merger sans savoir sur quelle branche on se trouve.","Supprimer trop tôt une branche non fusionnée."],studio:"merge"},
  {id:"git-conflict",level:2,title:"Résoudre un conflit",objective:"Comprendre puis résoudre un conflit simple.",explanations:["Un conflit apparaît lorsque deux branches ont modifié la même zone différemment.","Tu choisis le contenu final, supprimes les marqueurs, stages le fichier puis termines le merge avec un commit."],code:"<<<<<<< HEAD\n<h1>Bienvenue</h1>\n=======\n<h1>Mon portfolio</h1>\n>>>>>>> feature/title",details:["HEAD = ta branche actuelle.","Après résolution : git add fichier puis git commit."],mistakes:["Supprimer les marqueurs sans réfléchir au contenu final.","Oublier git add après résolution."],studio:"conflict"},
  {id:"git-restore-ignore",level:2,title:"git restore et .gitignore",objective:"Annuler une modification locale et exclure les fichiers inutiles ou sensibles.",explanations:["git restore fichier restaure la version suivie ; --staged retire un fichier de la staging area.",".gitignore indique les chemins que Git doit ignorer."],code:"git restore index.html\ngit restore --staged index.html\n\n# .gitignore\nnode_modules/\n.env\ndist/",details:[".gitignore lui-même peut être suivi.","Évite de versionner .env et node_modules/."],mistakes:["Utiliser restore sans comprendre ce qui sera perdu.","Committer .env."],studio:"restore"},
  {id:"git-remote",level:3,title:"Dépôt distant et git remote",objective:"Relier le dépôt local à un hébergement distant.",explanations:["Le remote est une adresse associée à un nom, généralement origin.","git remote -v affiche les remotes configurés."],code:"git remote add origin https://example.com/user/projet.git\ngit remote -v",details:["origin est une convention, pas une obligation.","Le dépôt local continue d'exister sans connexion réseau."],mistakes:["Croire qu'un commit est automatiquement envoyé sur GitHub.","Confondre branche locale et branche distante."],studio:"remote"},
  {id:"git-clone-push",level:3,title:"git clone et git push",objective:"Récupérer un projet puis publier ses commits.",explanations:["git clone crée une copie locale d'un dépôt distant.","git push envoie les commits locaux vers le remote."],code:"git clone https://example.com/user/todo-app.git\ngit push -u origin main",details:["-u mémorise la branche distante suivie.","Push n'ajoute pas automatiquement tes fichiers : ils doivent déjà être commités."],mistakes:["Push sans commit.","Travailler dans le mauvais dossier après clone."],studio:"push"},
  {id:"git-fetch-pull",level:3,title:"git fetch et git pull",objective:"Récupérer les changements distants proprement.",explanations:["fetch récupère les informations distantes sans modifier ta branche courante.","pull récupère puis intègre les nouveaux commits dans ta branche."],code:"git fetch\ngit pull",details:["fetch = observer/récupérer.","pull = fetch + intégration."],mistakes:["Faire pull au milieu de modifications locales non sauvegardées.","Ignorer un conflit après pull."],studio:"pull"},
  {id:"git-workflow",level:3,title:"Workflow quotidien et fiche mémo",objective:"Enchaîner naturellement les commandes essentielles.",explanations:["Commence par synchroniser, travaille sur une branche, vérifie, stage, commit puis push.","Git devient simple quand tu répètes le même petit cycle plutôt que mémoriser toutes les commandes."],code:"git pull\ngit switch -c feature/...\n# modifier\ngit status\ngit diff\ngit add .\ngit commit -m \"Message utile\"\ngit push",details:["Démarrer : init / clone.","Voir : status / diff / log --oneline.","Enregistrer : add / commit.","Branches : branch / switch / merge.","Remote : remote / fetch / pull / push."],mistakes:["Commits énormes et vagues.","git add . sans vérifier status.","Travailler toujours sur main."],studio:"workflow"}
];

